* {
  box-sizing    : border-box;
  margin        : 0;
  padding       : 0;
  user-select   : none;
  // font-family: samim;
}

body {
  display            : flex;
  justify-content    : center;
  align-items        : center;
  width              : 100%;
  height             : 100vh;
  background-repeat  : no-repeat;
  background-position: center center;
  background-size    : cover;
  position           : relative;
  margin             : 0;
  padding            : 0;

  #digital-screen {
    display            : flex;
    justify-content    : center;
    align-items        : center;
    background-repeat  : no-repeat;
    background-position: center center;
    background-size    : cover;
    position           : relative;
    background-image   : url('data:image/png;base64,');
    background-color   : #55bec2;

    .loader {
      background-color   : #fff;
      background-image   : url('data:image/gif;base64,');
      width              : 100%;
      height             : 100%;
      background-position: center;
      background-repeat  : no-repeat;
      background-size    : 50%;
      position           : absolute;
      z-index            : 10;
      top                : 0;
      right              : 0;
    }

    .transition {
      position: absolute;
      width   : 100%;
      height  : 100%;
      overflow: hidden;
      top     : 0;
      left    : 0;
      z-index : 1000;

      .pic_right,
      .pic_left {
        display         : flex;
        justify-content : center;
        align-items     : center;
        width           : 50%;
        height          : 100%;
        background-color: #063f5b;
        background-size : 100%;
        position        : absolute;
        transition      : transform 1s ease;
      }

      .pic_right {
        background-image   : url('data:image/png;base64,');
        right              : 0;
        transform          : translateX(0);
        background-position: left center;
      }

      .pic_left {
        background-image   : url('data:image/png;base64,');
        left               : 0;
        transform          : translateX(0);
        background-position: right center;
      }

      pointer-events: auto;

      &.active {
        pointer-events: none;
      }

      @keyframes slideOutRight {
        0% {
          transform: translateX(150%);
        }

        100% {
          transform: translateX(0);
        }
      }

      @keyframes slideOutLeft {
        0% {
          transform: translateX(-150%);
        }

        100% {
          transform: translateX(0);
        }
      }

      @keyframes slideInRight {
        0% {
          transform: translateX(0);
        }

        100% {
          transform: translateX(150%);
        }
      }

      @keyframes slideInLeft {
        0% {
          transform: translateX(0);
        }

        100% {
          transform: translateX(-150%);
        }
      }

      .pic_right.close {
        animation: slideOutRight 1s forwards;
      }

      .pic_left.close {
        animation: slideOutLeft 1s forwards;
      }

      .pic_right.open {
        animation: slideInRight 1s forwards;
      }

      .pic_left.open {
        animation: slideInLeft 1s forwards;
      }

      &.addGear {

        .pic_right.close,
        .pic_right.open {
          &:after {
            content            : '';
            position           : absolute;
            width              : 20vw;
            height             : 20vw;
            background-position: center;
            background-repeat  : no-repeat;
            background-size    : 100% 100%;
            animation          : rotateGear 3s linear infinite;
            left               : -10vw;
            top                : 35%;
            background-image   : url('data:image/png;base64,');
          }
        }
      }
    }

    &.ara {
      .animation {
        left: 0 !important;
      }

      .grade {
        left : unset !important;
        right: 20% !important;
        top  : 35%;
      }

      .feedback-description {
        padding-left   : 30%;
        padding-top    : 5%;
        bottom         : 20% !important;
        font-size      : 2vw;
        direction      : rtl;
        height         : 45%;
        width          : 80%;
        text-align     : center;
        display        : flex;
        justify-content: center;
        align-items    : center;
      }
    }

    &.eng {
      .animation {
        left: 55% !important;
      }

      .grade {
        left: 10% !important;
      }

      .feedback-description {
        position       : absolute !important;
        left           : 0 !important;
        bottom         : 20% !important;
        padding-left   : 6% !important;
        width          : 50% !important;
        text-align     : center !important;
        font-size      : 2vw;
        direction      : ltr;
        display        : flex;
        justify-content: center;
        align-items    : center;
        height         : 45%;
      }
    }
  }

  @keyframes rotateGear {
    0% {
      transform: rotate(0deg);
    }

    100% {
      transform: rotate(360deg);
    }
  }

  .logo {
    background-image   : url('data:image/png;base64,');
    background-repeat  : no-repeat;
    background-position: top right;
    background-size    : 100%100%;
    width              : 4vw;
    height             : 4vw;
    right              : 4%;
    top                : 1vw;
    position           : absolute;
    z-index            : 999999;
  }

  .main {
    .isSuccess {
      width          : 100%;
      height         : 100%;
      display        : flex;
      justify-content: center;
      align-items    : center;

      &.isEng {
        p {
          // letter-spacing: 0.01vw !important;
        }

        .round {
          direction: ltr;
        }
      }

      .zoki {
        .editFont {
          input {
            padding-top: 0.2vw !important;
          }
        }
      }
    }

    .editFont {
      input {
        padding-top: 0.2vw !important;
      }
    }

    &.isEng {
      p {
        letter-spacing: 0.01vw !important;
      }
    }

    .start-button {
      height             : 20vw;
      width              : 20vw;
      background-position: center;
      background-repeat  : no-repeat;
      background-size    : 100% 100%;
      position           : relative;
      z-index            : 9999;
      background-image   : url('data:image/png;base64,');
      animation          : zoom 30s infinite;
      -webkit-animation  : zoom 2.5s infinite ease-in-out;
      cursor             : pointer;
      background-color   : transparent;
      border             : 0;
    }

    @-webkit-keyframes zoom {
      0% {
        -webkit-transform: scale(0.8) rotate(-10deg);
        transform        : scale(0.8) rotate(-10deg);
      }

      50% {
        -webkit-transform: scale(1) rotate(10deg);
        transform        : scale(1) rotate(10deg);
      }

      100% {
        -webkit-transform: scale(0.8) rotate(-10deg);
        transform        : scale(0.8) rotate(-10deg);
      }
    }

    @keyframes zoom {
      0% {
        -webkit-transform: scale(0.8) rotate(-10deg);
        transform        : scale(0.8) rotate(-10deg);
      }

      50% {
        -webkit-transform: scale(1) rotate(10deg);
        transform        : scale(1) rotate(10deg);
      }

      100% {
        -webkit-transform: scale(0.8) rotate(-10deg);
        transform        : scale(0.8) rotate(-10deg);
      }
    }

    .zoki {
      width   : 100%;
      height  : 100%;
      overflow: hidden;

      .music {
        position         : absolute;
        width            : 5vw;
        height           : 5vw;
        background-size  : 100%;
        background-repeat: no-repeat;
        top              : 1%;
        left             : 1%;
        z-index          : 999;
        user-select      : none;

        &.play {
          background-image: url('data:image/png;base64,');
        }

        &.mute {
          background-image: url('data:image/png;base64,');
        }
      }

      /* Styles for popup */
      .popup {
        display            : none;
        position           : fixed;
        z-index            : 1000;
        width              : 70vw;
        height             : 35vw;
        background-size    : 100% 100%;
        background-repeat  : no-repeat;
        background-position: center;
        left               : 50%;
        top                : 50%;
        transform          : translate(-50%, -50%);
        padding            : 1vw;
        animation          : fadeIn 0.3s ease-out forwards;
        background-image   : url('data:image/png;base64,');
      }

      .popup-content {
        position       : relative;
        display        : flex;
        justify-content: center;
        align-items    : center;
        height         : 100%;
        padding-top    : 4vw;

        p {
          color    : white !important;
          font-size: 2.5vw;
        }
      }

      .popup-content .close {
        position         : absolute;
        top              : -1vw;
        right            : -2vw;
        color            : #aaa;
        cursor           : pointer;
        position         : absolute;
        width            : 6vw;
        height           : 6vw;
        background-size  : 100%;
        background-repeat: no-repeat;
        background-image : url('data:image/png;base64,');
      }

      .overlay {
        display         : none;
        position        : fixed;
        z-index         : 999;
        left            : 0;
        top             : 0;
        width           : 100%;
        height          : 100%;
        background-color: rgba(0, 0, 0, 0.5);
        animation       : fadeInOverlay 0.3s ease-out forwards;
      }

      @keyframes fadeIn {
        from {
          opacity: 0;
        }

        to {
          opacity: 1;
        }
      }

      @keyframes fadeInOverlay {
        from {
          opacity: 0;
        }

        to {
          opacity: 1;
        }
      }

      .popup-open {
        pointer-events: none;
      }

      .popup-closed {
        pointer-events: auto;
      }

      .information {
        position         : absolute;
        width            : 5vw;
        height           : 5vw;
        background-size  : 100%;
        background-repeat: no-repeat;
        top              : 12%;
        left             : 1%;
        z-index          : 999;
        background-image : url('data:image/png;base64,');

        &.disable {
          pointer-events: none;
        }

        &.none {
          pointer-events: none;
        }
      }

      &.display {

        .screen-question,
        .zoki-charecter {
          animation: fadeInOverlay 0.3s ease-out forwards;
        }
      }

      .zoki-charecter {
        opacity : 0;
        width   : 20%;
        height  : 20%;
        position: absolute;
        top     : 1%;
        right   : 12%;

        #zokicharecter {
          width : 10vw;
          height: 10vw;
        }

        &.hide {
          display: none;
        }
      }

      .screen-question {
        opacity        : 0;
        width          : 100%;
        height         : 100%;
        display        : flex;
        justify-content: center;
        align-items    : flex-end;

        .screen {
          width              : 95%;
          height             : 85%;
          position           : relative;
          margin             : 0 auto 0.5%;
          background-image   : url('data:image/png;base64,');
          background-repeat  : no-repeat;
          // pointer-events: none;
          background-position: bottom;
          background-size    : 100% 100%;
          z-index            : 2;
          display            : flex;
          align-items        : flex-end;
          justify-content    : center;

          .hand {
            position: relative;
            width   : 1vw;
            height  : 1vw;
            display : none;
            z-index : 99999 !important;

            &.display {
              display: block;
            }

            &.hide {
              display: none !important;
            }

            &::before {
              content            : '';
              width              : 4vw;
              height             : 5vw;
              bottom             : -2vw;
              left               : -5vw;
              z-index            : 99999 !important;
              position           : absolute;
              animation          : submit 0.5s linear 0.2s infinite alternate;
              background-image   : url(data:image/png;base64,);
              background-position: center;
              background-repeat  : no-repeat;
              background-size    : 100% 100%;
              transform          : rotate(135deg);
            }

            &.help {
              width : 0;
              height: 0;

              &:before {
                transform: rotate(332deg);
                animation: changeposition 0.5s linear 0.2s infinite alternate;
              }
            }

            &.display-answer {
              &::before {
                animation: displayAnswer 0.5s linear 0.2s infinite alternate;
                bottom   : -2vw;
                left     : 6vw;
                transform: rotate(-114deg);
              }
            }

            &.handEng {
              bottom: -2vw;
              left  : 0;
            }
          }

          .finished {
            width          : 100%;
            height         : 100%;
            display        : flex;
            position       : absolute;
            top            : 0;
            left           : 0;
            right          : 0;
            bottom         : 0;
            justify-content: center;
            align-items    : center;

            #robots {
              width : 100%;
              height: 100%;
            }
          }

          .check-button,
          .display-answer-button,
          .next-button,
          .levels {
            position         : absolute;
            left             : 15%;
            top              : -5%;
            background-image : url('data:image/png;base64,');
            background-size  : contain;
            background-repeat: no-repeat;
            z-index          : 100000;
            width            : 5%;
            height           : 15%;
            // cursor: pointer;
            pointer-events   : auto;

            &.disable {
              pointer-events: none;
            }
          }

          .check-button {
            pointer-events: none;

            &:not(.disable)::after {
              content       : '';
              position      : absolute;
              top           : 0;
              left          : 0;
              width         : 100%;
              height        : 66%;
              pointer-events: auto;
            }

            .levels {
              left          : 75%;
              top           : 30%;
              height        : 7vh;
              width         : 7vh;
              pointer-events: none;

              &.disable {
                pointer-events  : none;
                background-image: url('data:image/png;base64,');
              }

              p {
                height         : inherit;
                width          : inherit;
                color          : wheat !important;
                font-size      : 3vh !important;
                display        : flex;
                align-items    : center;
                justify-content: center;
                pointer-events : none;
              }
            }

            &.disable {
              background-image: url('data:image/png;base64,');
            }
          }

          .display-answer-button {
            background-image: url('data:image/png;base64,');
            left            : 27%;
            top             : -5%;
            pointer-events  : none;

            &:not(.disable)::after {
              content       : '';
              position      : absolute;
              top           : 0;
              left          : 0;
              width         : 100%;
              height        : 66%;
              pointer-events: auto;
            }

            &.disable {
              background-image: url('data:image/png;base64,');
            }
          }

          .next-button {
            background-image: url('data:image/png;base64,');
            right           : -1.5%;
            left            : unset;
            top             : 85%;
            width           : 9vh;
            height          : 9vh;
            z-index         : 9999;

            &.disable {
              background-image: url('data:image/png;base64,');
            }

            &.hide {
              display: none;
            }

            .next {
              &::before {
                animation: next 0.5s linear 0.2s infinite alternate;
                bottom   : 1vw;
                left     : -3vw;
                transform: rotate(142deg);
              }
            }
          }

          .question {
            width          : 100%;
            height         : 90%;
            // width: 108vh;
            margin-bottom  : 1vw;
            display        : none;
            justify-content: center;
            position       : relative;
            top            : 0;
            right          : 0;
            left           : 0;
            bottom         : 0;
            direction      : rtl;

            .break {
              flex-basis: 100%;
              height    : 0;
            }

            label {
              position: absolute;
              top     : -6vh;
              right   : 0;
            }

            // opacity: 0;
            &.active {
              opacity       : 1;
              display       : flex;
              pointer-events: auto;
            }

            .content {
              width          : 100%;
              height         : 100%;
              display        : inline-flex;
              justify-content: center;
              align-items    : center;
              flex-wrap      : wrap;
              align-content  : space-evenly;

              // direction: ltr;
              p {
                direction     : rtl;
                display       : flex;
                flex-wrap     : wrap;
                font-size     : 3vw;
                // font-family: samim;
                color         : #204a66 !important;
                font-weight   : bold;

                &.text {
                  direction     : rtl;
                  // font-family: samim;
                  font-weight   : bold;
                  color         : #204a66 !important;
                }

                &.number {
                  // font-family: ArialRounded;
                  color: #204a66 !important;
                }

                &.f-size {
                  font-size: 7vw;
                }
              }

              .fraction {
                display         : flex;
                justify-content : center;
                align-items     : center;
                flex-direction  : column;
                background-color: transparent !important;
                margin-left     : 0.5vw;
                margin-right    : 0.5vw;
                width           : auto;
                position        : relative;

                .line {
                  border-bottom: 0.2vw solid #204a66;
                  width        : 7vh;
                  margin       : 0.5vw 0;
                }

                .up,
                .down {
                  text-align: center;
                  display   : flex;
                  height    : 6vw;

                  p,
                  .ans {
                    margin     : 0.5vw 1vw 1vw 0.5vw !important;
                    padding    : 0 1.5vw;
                    display    : flex;
                    align-items: center;
                    font-size  : 3vw;
                  }
                }

                .up {

                  p,
                  .ans {
                    margin-top: 2vw !important;
                  }
                }
              }
            }

            @keyframes fadeIn {
              0% {
                opacity: 0;
              }

              100% {
                opacity: 1;
              }
            }

            @keyframes fadeout {
              0% {
                opacity: 1;
              }

              100% {
                opacity: 0;
              }
            }

            .chooses {
              display        : flex;
              width          : 100%;
              justify-content: space-evenly;
              animation      : fadeIn 4s;
              margin-top     : 1vw;

              .choose {
                width              : 15vw;
                height             : 6vw;
                display            : flex;
                justify-content    : center;
                align-items        : center;
                background-size    : 100% 100%;
                background-position: center;
                background-repeat  : no-repeat;
                background-image   : url('data:image/png;base64,');
                pointer-events     : auto;

                p {
                  pointer-events: none;
                  font-size     : 3vw;
                  // font-family: ArialRounded;
                }

                &.true,
                &.false {
                  p {
                    // color: #fff !important;
                    // pointer-events: none;
                  }
                }

                &.true {
                  background-image: url('data:image/png;base64,');
                }

                &.false {
                  background-image: url('data:image/png;base64,');
                  pointer-events  : none;
                }
              }
            }
          }
        }
      }

      input {
        font-size             : 3vw;
        width                 : 9vw;
        height                : 6vw;
        outline               : none;
        margin                : 0 0.2vw;
        padding               : 0;
        color                 : #204a66;
        letter-spacing        : 0.1vw;
        text-align            : center;
        // font-family        : ArialRounded;
        font-weight           : bold;
        background-image      : url('data:image/png;base64,');
        background-repeat     : no-repeat;
        background-position   : center;
        background-size       : 100%100%;
        border                : 0;
        background-color      : transparent;
        // font-family        : ArialRounded;
        caret-color           : #7e989d;

        &.right {
          background-image: url('data:image/png;base64,');
          pointer-events  : none;
        }

        &.false {
          background-image: url('data:image/png;base64,');
          pointer-events  : none;
        }

        &.inactive {
          background-image: url('data:image/png;base64,');
          pointer-events  : none;
        }

        &.showAnswer {
          background-image: url('data:image/png;base64,');
          pointer-events  : none;
        }

        &.displayinput {
          background-image: url('data:image/png;base64,');
          pointer-events  : none;
        }
      }

      .table {
        input {
          font-size          : 4vh;
          width              : 100%;
          // height: 4vw;
          // width: 15vh;
          height             : 100%;
          outline            : none;
          // margin: 0 0.5vw;
          padding            : 0;
          color              : #204a66;
          letter-spacing     : 0.5vw;
          text-align         : center;
          // font-family: ArialRounded;
          font-weight        : bold;
          background-repeat  : no-repeat;
          background-position: center;
          background-size    : 100%100%;
          border             : 0;
          background-color   : transparent;

          // font-family: ArialRounded;
          &.right {
            background-color: #41f97f;
            color           : #fff;
            pointer-events  : none;
          }

          &.false {
            background-color: #f789a1;
            color           : #fff;
          }

          &.inactive {
            pointer-events  : none;
            background-color: green;
          }

          &.showAnswer {
            background-color: #ffa162;
            color           : #fff;
            pointer-events  : none;
          }

          &.displayinput {
            background-color: #ffa162;
            color           : #fff;
            pointer-events  : none;
          }
        }
      }

      .roundOne {
        transition: 2s;
        opacity   : 0;
        z-index   : 0;
        display   : contents;

        &.activeRound {
          width     : 100%;
          transition: 2s;
          position  : unset !important;
          opacity   : 1;
        }
      }

      .round {
        width          : 100%;
        display        : flex;
        justify-content: center;
        align-items    : center;
        flex-wrap      : wrap;

        &.roundNone {
          display: none;
        }
      }

      .roundTwo {
        transition: 2s;
        opacity   : 0;
        z-index   : 0;

        &.activeRound {
          transition: 2s;
          width     : 100%;
          position  : unset !important;
          opacity   : 1 !important;
        }

        .chooses {
          pointer-events: none;

          .choose {
            pointer-events: none;
          }
        }

        &.display {
          opacity       : 1;
          pointer-events: auto;

          .chooses {
            pointer-events: auto;

            .choose {
              pointer-events: auto;
            }
          }
        }
      }
    }

    .nextContent {
      width          : 100%;
      height         : 100%;
      z-index        : 100;
      display        : flex;
      position       : absolute;
      top            : 0;
      left           : 0;
      justify-content: center;
      align-items    : center;
      z-index        : 1000;

      .character {
        width                 : 55vw;
        height                : 35vw;
        position              : relative;
        background-size       : contain;
        background-position   : center center;
        background-repeat     : no-repeat;
        // animation          : fade .1s ease-in-out;
        background-image      : url('data:image/png;base64,');
        color                 : #55bec2;
        font-size             : 1.5vw;
        font-weight           : bold;
        display               : flex;
        justify-content       : center;
        align-items           : center;

        .percentage {
          position  : absolute;
          top       : 7%;
          right     : 26%;
          text-align: center;
          width     : 10%;
        }

        .grade {
          width         : 35%;
          text-align    : center;
          position      : absolute;
          top           : 30%;
          left          : 35%;
          font-size     : 2vw;
          // &.lower {
          //     display: none;
          // }
        }

        p {
          font-weight: bold;
          color      : white;
        }

        .progress {
          display        : flex;
          justify-content: center;
          position       : absolute;
          top            : -8vw;
          right          : 15vw;
          width          : 20vw;
          height         : 22vw;
          top            : -8vw;
          right          : 14vw;
          width          : 30vw;
          height         : 20vw;

          &.eng {
            transform: scaleX(-1);

            .box_score {
              transform: scaleX(-1);
              direction: ltr;
            }
          }

          #stars,
          #progressbar {
            display: none;

            &.active {
              display: block;
            }
          }

          .eng {
            transform: scaleX(-1);
          }

          .box_score {
            display          : flex;
            justify-content  : space-evenly;
            align-items      : center;
            background-image : url(data:image/png;base64,);
            width            : 10vw;
            height           : 4vw;
            padding          : 0.5vw;
            background-size  : 100% 100%;
            background-repeat: no-repeat;
            position         : absolute;
            bottom           : 1%;
            left             : 30%;
            direction        : ltr;

            p {
              font-family: lexend-regular !important;
              color      : black;
              font-size  : 2vw;
            }
          }
        }

        .animation {
          width   : 40%;
          height  : 70%;
          position: absolute;
          top     : 16%;

          #zokihappy,
          #zokisad {
            width        : 100%;
            height       : 85%;
            margin-bottom: 1vh;
          }
        }

        .buttons {
          position       : absolute;
          bottom         : 0vh;
          width          : 40%;
          height         : 5vw;
          right          : 0;
          left           : 0;
          margin         : 0 auto;
          display        : flex;
          justify-content: space-around;
          align-items    : center;

          button {
            width              : 8vw;
            height             : 8vw;
            border-radius      : 50%;
            background-size    : contain;
            background-position: center center;
            background-repeat  : no-repeat;
            border             : 0;
            background-color   : transparent;

            &.next {
              background-image: url(data:image/png;base64,);
            }

            &.home {
              background-image: url('data:image/png;base64,');
            }

            &:focus {
              outline: none;
              opacity: 0.5;
            }
          }
        }
      }
    }

    @-webkit-keyframes fade {
      from {
        opacity: 0;
      }

      to {
        opacity: 1;
      }
    }

    @keyframes fade {
      from {
        opacity: 0;
      }

      to {
        opacity: 1;
      }
    }

    @keyframes submit {
      from {
        bottom: -2vw;
        left  : -6vw;
      }

      to {
        bottom: -1vw;
        left  : -8vw;
      }
    }

    @keyframes displayAnswer {
      from {
        bottom: -2vw;
        left  : 6vw;
      }

      to {
        bottom: -1vw;
        left  : 8vw;
      }
    }

    @keyframes next {
      from {
        bottom: 3vw;
        left  : -5vw;
      }

      to {
        bottom: 1vw;
        left  : -3vw;
      }
    }

    @keyframes changeposition {
      from {
        bottom: 0vw;
        left  : 6vw;
      }

      to {
        bottom: -1vw;
        left  : 7vw;
      }
    }

    .character {
      &.show {
        background-image: url('data:image/png;base64,');
      }
    }
  }

  .flex {
    display    : flex;
    align-items: center;
  }

  .flexcloumn {
    display       : flex;
    flex-direction: column;
  }

  .flexcenter {
    justify-content: center;
  }
}

.table {
  display         : flex;
  justify-content : center;
  align-items     : center;
  width           : 115vh;
  height          : 35vh;
  padding         : 1vh;
  background-color: #cadadd82;
  border-radius   : 2vw;

  .inner_table {
    width        : 100%;
    height       : 100%;
    border-radius: 2vw;
    border       : solid 0.5vh #65858e;
    display      : flex;
    background   : white;

    .column_1,
    .column_2,
    .column_3,
    .column_4 {
      height      : 100%;
      border-right: 0.4vh solid #65858e;

      .header_table,
      .center_table,
      .bottom_table {
        width          : 100%;
        height         : calc(100% / 3);
        display        : flex;
        justify-content: center;
        align-items    : center;
        border-bottom  : 0.4vh solid #65858e;
      }

      .bottom_table {
        border-bottom: 0;
      }
    }

    .column_1 {
      width: 20%;

      .header_table {
        background-color: #f9aa8e;
        border-radius   : 1.5vw 0 0 0.5vw;
      }

      .bottom_table {
        input {

          &.false,
          &.showAnswer,
          &.true {
            border-radius: 0 0 0 1.5vw !important;
          }
        }
      }
    }

    .column_2 {
      width: 10%;

      .header_table {
        background-color: #95dbad;
      }
    }

    .column_3 {
      width: 35%;

      .header_table {
        background-color: #fed7a0;
      }
    }

    .column_4 {
      width       : 35%;
      border-right: 0;

      .header_table {
        background-color: #abe1fa;
        border-radius   : 0 1.5vw 0.5vw 0;
      }

      .bottom_table {
        input {

          &.false,
          &.showAnswer,
          &.true {
            border-radius: 0 0 1.5vw 0 !important;
          }
        }
      }
    }
  }
}

.sign {
  width              : 12vh;
  height             : 9vh;
  margin             : 0 3vh;
  display            : flex;
  justify-content    : center;
  align-items        : center;
  background-size    : 100% 100%;
  background-position: center;
  background-repeat  : no-repeat;
  background-image   : url(data:image/png;base64,);

  p {
    pointer-events: none;
    font-size     : 7vh !important;
    // font-family: ArialRounded !important;
  }
}